WITH base AS (SELECT id, device, browser, started_at, TO_DATE(started_at) AS started_at_date FROM sessions WHERE device <> 'desktop') SELECT id, device, browser, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, LAST_VALUE(browser, TRUE) OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser_2, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at_date DESC, id) AS event_seq FROM base
